/// <summary>
/// Returns the storage category "xslt-transformation" which is needed to access the files, but protected.
/// </summary>
/// <returns>The storage category "xslt-transformation"</returns>
public str AVADAIAzureStorageCategory()
{
    return AzureStorageCategory;
}

/// <summary>
/// Use this to query the storage category for XSLT transformations.
/// </summary>
/// <returns>The storage category for XSLT transformations</returns>
public static str AVADAIGetAzureStorageCategory()
{
    DMFXSLTUploadStrategy strategy = new DMFXSLTUploadStrategy();

    return strategy.AVADAIAzureStorageCategory();
}
